              <span style={{ color: "#4ade80" }}>&quot;failed&quot;</span>)
              {"\n"}ns.<span style={{ color: "#7aa2ff" }}>serve_replays</span>(<span style={{ color: "#b69cff" }}>lambda</span> t: handle(t, dry_run=<span style={{ color: "#b69cff" }}>True</span>))
